using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Web.Script.Serialization;

namespace CodexQuota {
  public static class UpdateCoreTests {
    static int passed,failed;
    static readonly string[] Required={"CodexQuota.exe","CodexQuota.Updater.exe","server.mjs","codex-account.mjs","usage-model.mjs","activity-model.mjs","activity-collector.mjs","activity-tracker.mjs","Start-Panel.ps1","version.json"};
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Throws(Action action){bool threw=false;try{action();}catch{threw=true;}Check(threw,"Expected rejection");}
    static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static string Temp(){string path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"CodexQuotaUpdateTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    static string Digest(byte[] value){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(value)).Replace("-","").ToLowerInvariant();}
    static Dictionary<string,byte[]> Files(){var files=new Dictionary<string,byte[]>();foreach(string name in Required)files.Add(name,Encoding.UTF8.GetBytes(name=="version.json"?"{\"version\":\"2.2.0\"}":"new-"+name));return files;}
    static string Manifest(Dictionary<string,byte[]> files){var entries=new List<object>();foreach(var pair in files)entries.Add(new {path=pair.Key,sha256=Digest(pair.Value)});return new JavaScriptSerializer().Serialize(new {version="2.2.0",files=entries});}
    static string Zip(string root,Dictionary<string,byte[]> files,string manifest,Action<ZipArchive> extra){string path=System.IO.Path.Combine(root,"update.zip");using(var archive=ZipFile.Open(path,ZipArchiveMode.Create)){Write(archive,"update-manifest.json",Encoding.UTF8.GetBytes(manifest));foreach(var pair in files)Write(archive,pair.Key,pair.Value);if(extra!=null)extra(archive);}return path;}
    static void Write(ZipArchive archive,string path,byte[] bytes){using(var output=archive.CreateEntry(path).Open())output.Write(bytes,0,bytes.Length);}
    static UpdatePlan Fixture(string root,bool includeConfig){var files=Files();if(includeConfig)files.Add("update-source.json",Encoding.UTF8.GetBytes("new-config"));string package=System.IO.Path.Combine(root,"package");UpdateCore.StagePackage(Zip(root,files,Manifest(files),null),package,"2.2.0");string install=System.IO.Path.Combine(root,"install");Directory.CreateDirectory(install);foreach(string name in Required)File.WriteAllText(System.IO.Path.Combine(install,name),name=="version.json"?"{\"version\":\"2.1.0\"}":"old-"+name);return new UpdatePlan {InstallRoot=install,PackageDirectory=package,BackupDirectory=System.IO.Path.Combine(root,"backup"),FromVersion="2.1.0",ToVersion="2.2.0"};}
    public static int Main(){
      Test("numeric versions",delegate{Check(UpdateCore.IsNewer("2.10.0","2.9.0"),"2.10 must exceed 2.9");Check(!UpdateCore.IsNewer("2.1.0","2.1.0"),"equal version");Check(!UpdateCore.IsNewer("2.0.0","2.1.0"),"downgrade");});
      Test("allowlist rejects ambiguous and escaped paths",delegate{Check(UpdateCore.IsAllowedPath("public/app.js"),"valid public asset");foreach(string name in new[]{"../server.mjs","C:/server.mjs","public\\app.js","/server.mjs","public/../server.mjs","server.mjs:stream",".data/state.json","custom.exe"})Check(!UpdateCore.IsAllowedPath(name),"Accepted "+name);});
      Test("valid package verifies all required hashes",delegate{string root=Temp();var files=Files();var manifest=UpdateCore.StagePackage(Zip(root,files,Manifest(files),null),System.IO.Path.Combine(root,"stage"),"2.2.0");Check(manifest.Files.Count==Required.Length,"missing files");Check(UpdateCore.HashFile(System.IO.Path.Combine(root,"stage","server.mjs"))==Digest(files["server.mjs"]),"hash mismatch");});
      Test("tampered zip fails before installation",delegate{string root=Temp();var files=Files();string manifest=Manifest(files);files["server.mjs"]=Encoding.UTF8.GetBytes("tampered");Throws(delegate{UpdateCore.StagePackage(Zip(root,files,manifest,null),System.IO.Path.Combine(root,"stage"),"2.2.0");});});
      Test("traversal duplicate and symbolic-link ZIP entries rejected",delegate{foreach(string mode in new[]{"traversal","duplicate","symlink"}){string root=Temp();var files=Files();string zip=Zip(root,files,Manifest(files),delegate(ZipArchive archive){if(mode=="traversal")Write(archive,"../outside",new byte[]{1});else if(mode=="duplicate")Write(archive,"server.mjs",new byte[]{1});else{var entry=archive.CreateEntry("public/app.js");entry.ExternalAttributes=(0xA000|0x1ff)<<16;using(var output=entry.Open())output.WriteByte(1);}});Throws(delegate{UpdateCore.StagePackage(zip,System.IO.Path.Combine(root,"stage"),"2.2.0");});}});
      Test("required file and requested version validated",delegate{string root=Temp();var files=Files();files.Remove("CodexQuota.Updater.exe");Throws(delegate{UpdateCore.StagePackage(Zip(root,files,Manifest(files),null),System.IO.Path.Combine(root,"stage"),"2.2.0");});root=Temp();files=Files();string zip=Zip(root,files,Manifest(files),null);Throws(delegate{UpdateCore.StagePackage(zip,System.IO.Path.Combine(root,"stage"),"2.3.0");});});
      Test("apply preserves personal data run state and source config",delegate{string root=Temp();var plan=Fixture(root,true);Directory.CreateDirectory(System.IO.Path.Combine(plan.InstallRoot,".data"));Directory.CreateDirectory(System.IO.Path.Combine(plan.InstallRoot,".run"));File.WriteAllText(System.IO.Path.Combine(plan.InstallRoot,".data","state.json"),"personal");File.WriteAllText(System.IO.Path.Combine(plan.InstallRoot,".run","state"),"running");File.WriteAllText(System.IO.Path.Combine(plan.InstallRoot,"update-source.json"),"personal-config");UpdateCore.ApplyFiles(plan);Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"CodexQuota.exe"))=="new-CodexQuota.exe","not updated");Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"update-source.json"))=="personal-config","config replaced");Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,".data","state.json"))=="personal","data replaced");Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,".run","state"))=="running","run state replaced");});
      Test("locked later file rolls back earlier replacements",delegate{string root=Temp();var plan=Fixture(root,false);using(var locked=new FileStream(System.IO.Path.Combine(plan.InstallRoot,"server.mjs"),FileMode.Open,FileAccess.Read,FileShare.Read)){Throws(delegate{UpdateCore.ApplyFiles(plan);});Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"CodexQuota.exe"))=="old-CodexQuota.exe","exe rollback failed");Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"CodexQuota.Updater.exe"))=="old-CodexQuota.Updater.exe","updater rollback failed");}Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"server.mjs"))=="old-server.mjs","locked file changed");});
      Test("startup failure can restore a successfully applied package",delegate{string root=Temp();var plan=Fixture(root,true);File.WriteAllText(System.IO.Path.Combine(plan.InstallRoot,"update-source.json"),"personal-config");File.Delete(System.IO.Path.Combine(plan.InstallRoot,"activity-tracker.mjs"));UpdateCore.ApplyFiles(plan);UpdateCore.RestoreAppliedFiles(plan);Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"CodexQuota.exe"))=="old-CodexQuota.exe","old exe not restored");Check(!File.Exists(System.IO.Path.Combine(plan.InstallRoot,"activity-tracker.mjs")),"new-only file not removed");Check(File.ReadAllText(System.IO.Path.Combine(plan.InstallRoot,"update-source.json"))=="personal-config","source config changed");});
      Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;
    }
  }
}
